const char *map[] = {"abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
const int len[] = {3, 3, 3, 3, 3, 4, 3, 4};

void dfs(char *p, int d, char *buff, char **pp, int *n) {
  const char *m;

  if (!*p) {
    pp[*n] = strdup(buff);
    (*n)++;
    return;
  }

  m = map[(*p) - '2'];
  while (*m) {
    buff[d] = *m;
    dfs(p + 1, d + 1, buff, pp, n);
    m++;
  }
}

char **letterCombinations(char *digits, int *returnSize) {
  char **pp;
  char *buff;
  char *d;
  int n, l;

  *returnSize = 0;

  if (!digits || !*digits) {
    return NULL;
  }

  n = 1;
  d = digits;
  while (*d) {
    n = n * len[*d - '2'];
    d++;
  }

  *returnSize = n;
  l = d - digits;
  pp = malloc(n * sizeof(char *));
  buff = malloc(l + 1);
  buff[l] = 0;

  n = 0;
  dfs(digits, 0, buff, pp, &n);
  free(buff);
  return pp;
}

class Solution {
public:
  vector<string> letterCombinations(string digits) {
    vector<string> res;
    if (digits.empty()) return res;
    vector<string> map = {"abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
    res.push_back("");
    for (char d : digits) {
      vector<string> next;
      for (const string &prefix : res) {
        for (char c : map[d - '2']) {
          next.push_back(prefix + c);
        }
      }
      res = next;
    }
    return res;
  }
};

func letterCombinations(digits string) []string {
	if len(digits) == 0 {
		return nil
	}
	mapping := []string{"abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"}
	res := []string{""}
	for i := 0; i < len(digits); i++ {
		var next []string
		for _, prefix := range res {
			for _, c := range mapping[digits[i]-'2'] {
				next = append(next, prefix+string(c))
			}
		}
		res = next
	}
	return res
}

class Solution {
  public List<String> letterCombinations(String digits) {
    List<String> res = new ArrayList<>();
    if (digits.isEmpty()) {
      return res;
    }
    String[] map = { "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz" };
    res.add("");
    for (int i = 0; i < digits.length(); i++) {
      List<String> next = new ArrayList<>();
      String letters = map[digits.charAt(i) - '2'];
      for (String prefix : res) {
        for (int j = 0; j < letters.length(); j++) {
          next.add(prefix + letters.charAt(j));
        }
      }
      res = next;
    }
    return res;
  }
}

class Solution:
    def letterCombinations(self, digits: str) -> List[str]:
        if not digits:
            return []
        mapping = ["abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"]
        res = [""]
        for d in digits:
            res = [prefix + c for prefix in res for c in mapping[int(d) - 2]]
        return res

impl Solution {
  pub fn letter_combinations(digits: String) -> Vec<String> {
    if digits.is_empty() {
      return vec![];
    }
    let map = ["abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"];
    let mut res = vec![String::new()];
    for d in digits.chars() {
      let letters = map[(d as u8 - b'2') as usize];
      let mut next = vec![];
      for prefix in &res {
        for c in letters.chars() {
          next.push(format!("{}{}", prefix, c));
        }
      }
      res = next;
    }
    res
  }
}

const letterCombinations = (digits: string): string[] => {
  if (digits.length === 0) return [];
  const map = ['abc', 'def', 'ghi', 'jkl', 'mno', 'pqrs', 'tuv', 'wxyz'];
  let res: string[] = [''];

  for (const d of digits) {
    const letters = map[Number(d) - 2];
    const next: string[] = [];
    for (const prefix of res) {
      for (const c of letters) {
        next.push(prefix + c);
      }
    }
    res = next;
  }

  return res;
};
